WITH valid AS (SELECT id, product_id, last_restock, CASE WHEN quantity >= 218 THEN 'High' WHEN quantity >= 107 THEN 'Medium' ELSE 'Low' END AS quantity_level FROM inventory WHERE last_restock > DATE '2023-11-24'), enriched AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS event_seq, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) AS row_seq, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) AS row_seq_2, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) AS event_seq_2, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS event_seq_3 FROM valid), enriched_inventory AS (SELECT *, AVG(row_seq_2) OVER (PARTITION BY product_id ORDER BY event_seq, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS row_seq_2_avg_6_prior, LAG(event_seq, 1) OVER (PARTITION BY product_id ORDER BY event_seq, id) AS prev_event_seq FROM enriched) SELECT product_id, AVG(event_seq_3) AS avg_event_seq_3, APPROX_PERCENTILE(row_seq_2, 0.5) AS row_seq_2_p50, COUNT(*) AS num_rows, PERCENTILE_APPROX(event_seq_2, ARRAY(0.25, 0.5, 0.75)) AS event_seq_2_quartiles FROM enriched_inventory GROUP BY product_id ORDER BY avg_event_seq_3 NULLS LAST
